selector_to_html = {"a[href=\"#deepseek-v3-training-test\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">7. DeepSeek-V3 Training Test<a class=\"headerlink\" href=\"#deepseek-v3-training-test\" title=\"Link to this heading\">#</a></h2><p>Requires 4 GPUs. Uses expert parallelism and per-operator backend configuration for grouped GEMM.</p>", "a[href=\"#dataset\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Dataset<a class=\"headerlink\" href=\"#dataset\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#prepare-transformerengine-fl\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">4. Prepare TransformerEngine-FL<a class=\"headerlink\" href=\"#prepare-transformerengine-fl\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#cuda-nvidia\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">CUDA (NVIDIA)<a class=\"headerlink\" href=\"#cuda-nvidia\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#metax\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">MetaX<a class=\"headerlink\" href=\"#metax\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#end-to-end-use-case-transformerengine-fl-megatron-lm-fl-flagscale\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">End-to-End Use Case: TransformerEngine-FL + Megatron-LM-FL + FlagScale<a class=\"headerlink\" href=\"#end-to-end-use-case-transformerengine-fl-megatron-lm-fl-flagscale\" title=\"Link to this heading\">#</a></h1><p>This guide walks through an end-to-end training workflow using TransformerEngine-FL, Megatron-LM-FL, and FlagScale together, performed on both CUDA (NVIDIA) and MetaX platforms.</p>", "a[href=\"#flagos-release-image-v0-2-0-rc2-recommended\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">FlagOS Release Image (v0.2.0-rc2, Recommended)<a class=\"headerlink\" href=\"#flagos-release-image-v0-2-0-rc2-recommended\" title=\"Link to this heading\">#</a></h3><p>Includes torch 2.4.0a0, triton 3.0.0, trans-engine 2.14.0. Suitable for 100B+ parameter model pre-training.</p>", "a[href=\"#prepare-dataset-and-tokenizer\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">5. Prepare Dataset and Tokenizer<a class=\"headerlink\" href=\"#prepare-dataset-and-tokenizer\" title=\"Link to this heading\">#</a></h2><h3>Dataset<a class=\"headerlink\" href=\"#dataset\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#qwen3-training-test\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">6. Qwen3 Training Test<a class=\"headerlink\" href=\"#qwen3-training-test\" title=\"Link to this heading\">#</a></h2><p>Requires 4 GPUs. The <code class=\"docutils literal notranslate\"><span class=\"pre\">te_fl_prefer</span></code> parameter controls backend selection \u2014 use <code class=\"docutils literal notranslate\"><span class=\"pre\">vendor</span></code> for vendor-specific implementations or <code class=\"docutils literal notranslate\"><span class=\"pre\">reference</span></code> for pure PyTorch fallback.</p>", "a[href=\"#docker-environment\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">1. Docker Environment<a class=\"headerlink\" href=\"#docker-environment\" title=\"Link to this heading\">#</a></h2><h3>FlagOS Release Image (v0.2.0-rc2, Recommended)<a class=\"headerlink\" href=\"#flagos-release-image-v0-2-0-rc2-recommended\" title=\"Link to this heading\">#</a></h3><p>Includes torch 2.4.0a0, triton 3.0.0, trans-engine 2.14.0. Suitable for 100B+ parameter model pre-training.</p>", "a[href=\"#prepare-megatron-lm-fl\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">3. Prepare Megatron-LM-FL<a class=\"headerlink\" href=\"#prepare-megatron-lm-fl\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#tokenizer\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Tokenizer<a class=\"headerlink\" href=\"#tokenizer\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#notes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">8. Notes<a class=\"headerlink\" href=\"#notes\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#prepare-flagscale\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">2. Prepare FlagScale<a class=\"headerlink\" href=\"#prepare-flagscale\" title=\"Link to this heading\">#</a></h2>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
